module.exports = [
{"id":"aoerliangfengweikaojitui","name":"奥尔良风味烤鸡腿","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":5,"difficultyText":"★★★★★","calories":"955 大卡","time":"","servings":"1-2人份","description":"奥尔良风味烤鸡腿是一道简单易做的菜，富含蛋白质和铁。总共花费约 3 小时，其中手动操作时间约 20 分钟。","tags":["烤","进阶挑战"],"ingredients":[{"name":"手枪腿鸡腿","amount":"2 只（每个手枪腿大约重 200g，共约 400g）","optional":false,"amountValue":2,"amountUnit":"只"},{"name":"新奥尔良烤翅调料","amount":"15 - 20 g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"水 ≥30 mL","amount":"","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"解冻手枪腿鸡腿并洗净。","group":""},{"text":"手枪腿鸡腿改花刀：在每只手枪腿鸡腿的\"枪管\"处，平行于\"枪管\"用小刀切 4-6 刀，下刀尽可能深。","group":""},{"text":"拿一个锅，**加入 15 - 20 g 新奥尔良烤翅调料粉、5 g 盐，≥30 mL 水**。","group":""},{"text":"将改完花刀的手枪腿鸡腿放入锅内，搅匀。","group":""},{"text":"将整个锅放入冰箱冷藏层**冷藏 2 - 4 小时**，时间越长越入味。","group":""},{"text":"在烤盘上放一张铝箔纸，将鸡腿取出，皮面向下放上去（不要弄破铝箔纸）。**丢弃锅内剩余的液体。**","group":""},{"text":"放入烤箱中上层，按照如下参数烘烤：","group":""},{"text":"取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）","group":""},{"text":"对所有手枪腿鸡腿翻面。","group":""},{"text":"放入烤箱上层，按照如下参数烘烤：","group":""},{"text":"取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）","group":""},{"text":"放入烤箱上层，按照如下参数烘烤：","group":""},{"text":"取出，将烤盘中的油脂倒到大碗里备用。（不要弄破铝箔纸）","group":""},{"text":"取一个小碗，**按照 10:1 - 2:1 体积比，加入大碗中的油脂和豉油调味汁**。调味汁越多越咸，具体加入量取决于个人口味。","group":""},{"text":"抓住手枪腿鸡腿根部，蘸取小碗中的液体，可使用餐巾纸或手套隔油。现在可以直接从烤盘铝箔纸上享用奥尔良风味烤鸡腿了。","group":""}],"tips":["冷藏中途可以拿出搅匀。冷藏时间切勿过长。","该指南基于的烤箱参数为_**容积 25 L，功率 1400 W**_。","若烤箱功率低于/高于此值，可以适当延长/缩短烤箱定时，但请确保鸡腿是熟的。"]},
{"id":"aomenshibanmianzhiniuroufan","name":"澳门湿版免治牛肉饭","category":"荤菜","categoryKey":"meat_dish","emoji":"🥩","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/澳门湿版免治牛肉饭/澳门湿版免治牛肉饭.jpg","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"1011 大卡","time":"","servings":"1-2人份","description":"这是一道经典的澳门葡式风味快餐，牛肉碎嫩滑咸香，裹着浓郁酱汁和半熟蛋液，拌入米饭后口感油润诱人。牛肉末提供优质蛋白质，搭配鸡蛋和洋葱，营养均衡管饱。操作步骤简单易上手，特别适合新手尝试，从备料到出锅大约只需 30 分钟。","tags":["汤","新手友好"],"ingredients":[{"name":"牛肉末","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"洋葱 半个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"鸡蛋","amount":"1 个（用于制作水波蛋或半熟煎蛋）","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"生抽","amount":"3 汤匙（1 汤匙用于腌制，2 汤匙用于料汁）","optional":false,"amountValue":null,"amountUnit":""},{"name":"老抽 半汤匙","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"番茄酱","amount":"2 汤匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"白糖 半汤匙","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"料酒","amount":"1 汤匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"淀粉","amount":"1 汤匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"清水","amount":"50ml","optional":false,"amountValue":50,"amountUnit":"ml"}],"steps":[{"text":"将 200g 牛肉末放入碗中，加入 1 汤匙生抽、半汤匙白糖和 2g 黑胡椒，搅拌均匀，**等待腌制 10 分钟**。","group":""},{"text":"将半个洋葱切成小丁，备用。","group":""},{"text":"调制料汁：在碗中加入 2 汤匙生抽、2 汤匙番茄酱、1 汤匙料酒、1 汤匙淀粉、半汤匙老抽和 50ml 清水，搅拌均匀备用。","group":""},{"text":"另起一锅，制作一个水波蛋或半熟煎蛋，备用。","group":""},{"text":"热锅，放入 10g 黄油。待黄油融化后，放入洋葱丁，小火煎熟至散发香味。","group":""},{"text":"加入腌制好的牛肉末，与洋葱一起翻炒至牛肉变色。","group":""},{"text":"倒入调好的料汁，撒上 2g 黑胡椒，继续炒制直至汤汁变粘稠后关火。","group":""},{"text":"将炒好的免治牛肉浇在热米饭上，放上提前准备好的水波蛋或半熟煎蛋。","group":""},{"text":"（可选）表面撒上 5g 切好的小葱花作装饰。","group":""}],"tips":["如果没有黄油，使用普通食用油也可以，但黄油会增加独特的奶香味。","吃的时候将半熟的蛋黄戳破，与牛肉和米饭拌匀食用，口感最佳。"]},
{"id":"bajisitanniuroukali","name":"巴基斯坦牛肉咖喱","category":"荤菜","categoryKey":"meat_dish","emoji":"🥩","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/巴基斯坦牛肉咖喱/巴基斯坦牛肉咖喱.png","hasImage":true,"difficulty":5,"difficultyText":"★★★★★","calories":"602 大卡","time":"","servings":"1人份","description":"这道巴基斯坦风味咖喱牛肉香浓软糯，酸辣开胃，带着浓郁的香料气息。牛肉提供优质蛋白，搭配番茄和酸奶，营养均衡。做法不算繁琐，但慢炖需要一点耐心，很适合在闲暇的周末从容准备。从头到尾大约两个半小时，就能端出一锅温暖的异国美味。","tags":["进阶挑战"],"ingredients":[{"name":"番茄🍅","amount":"4 个","optional":false,"amountValue":4,"amountUnit":"个"},{"name":"螺丝椒","amount":"2 个（大个的）","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"原味酸奶","amount":"1 盒","optional":false,"amountValue":null,"amountUnit":""},{"name":"Masala 粉一包","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"蒜粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"姜粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"}],"steps":[{"text":"全部螺丝椒切成段状，备用","group":""},{"text":"全部番茄打成番茄蓉，备用","group":""},{"text":"牛肉切成 2cm 的小块，洗净备用","group":""},{"text":"炒锅中倒入一层油（用来防止番茄蓉沸腾蒸发）","group":""},{"text":"倒入番茄蓉，持续搅拌 2-3 分钟，等待它越变越红","group":""},{"text":"加入 5g 蒜粉，5g 姜粉和 1 包 50g 的 Masala 粉，搅拌均匀","group":""},{"text":"加入牛肉和螺丝椒段，搅拌均匀","group":""},{"text":"加入 1 盒酸奶（为了让整个酱汁变得粘稠），搅拌均匀","group":""},{"text":"将整锅材料转移到电饭煲/电炖锅，并加入 250 ml 的水，开启炖肉/慢炖档，设定时间 2-3 个小时","group":""},{"text":"等待完成，开锅检查牛肉软糯，就可以吃了","group":""}],"tips":["这道菜是从一个巴基斯坦的朋友那里偷师而来，特地整理了笔记，绝对正宗。","通常配以 烙饼(roti)、馕(naan) 或 米饭 食用。","如果想做 Chicken karahi 流程几乎是一样的，除了是先用油和各种花椒胡椒煎鸡肉变黄。"]},
{"id":"baicaizhuroudunfentiao","name":"白菜猪肉炖粉条","category":"荤菜","categoryKey":"meat_dish","emoji":"🥓","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"1880 大卡","time":"45分钟","servings":"1-2人份","description":"猪肉白菜炖粉条是东北地区经典的家常炖菜，汤汁浓郁咸鲜，五花肉软烂、粉条吸饱肉香后滑韧入味，白菜清甜解腻。整道菜荤素搭配均衡，能提供蛋白质、维生素和碳水化合物，营养饱腹。制作过程需要一些耐心，特别是粉条处理和炖煮火候，对新手有一定挑战，但按步骤操作不易失败，从头到尾大约需要 45 分钟即可上桌。","tags":["汤"],"ingredients":[{"name":"五花肉","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"大白菜","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"土豆干粉条","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"十三香","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"鸡精","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"食用盐","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"老抽","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"生抽","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"锅内烧水，水开后放入干粉条，煮 5 分钟后同水一起倒出容器中，盖上盖子继续浸泡泡 备用（第一步先做这个，期间可以进行以下步骤）","group":""},{"text":"五花肉切 3mm 的肉片，备用","group":""},{"text":"大白菜嫩叶与白菜帮子分开切成 2 份菜片，备用","group":""},{"text":"热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高","group":""},{"text":"放入五花肉，保持翻炒至肉变色","group":""},{"text":"加入老抽，炒 **1 分钟**，给肉上色","group":""},{"text":"加入白菜帮子，加入食用盐、生抽，炒一分钟（如果粘锅，烹入 10ml 水）","group":""},{"text":"加水没过所有食材，加入鸡精 ，十三香，沸腾后，将火调小然后**等待 20 分钟**","group":""},{"text":"粉条滤水切成小段放入碗中 备用","group":""},{"text":"加入白菜嫩叶，炒匀后将粉条放在菜上方，加盖再煮 **5 分钟**","group":""},{"text":"尝味、关火，收汁","group":""}],"tips":["土豆干粉条煮制时间长，可以放在第一步，期间进行其他步骤","最后一步尝味，如果发现有味道淡、未熟，继续加盖煮一段时间"]},
{"id":"chizhipaigu","name":"豉汁排骨","category":"荤菜","categoryKey":"meat_dish","emoji":"🧃","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"1513 大卡","time":"","servings":"1-2人份","description":"这是一道粤式茶楼里的人气蒸点，豉香醇厚，排骨滑嫩脱骨。排骨提供优质蛋白和钙质，发酵豆豉增添风味也更利吸收。做法需经过泡洗、腌制和控火蒸制，对新手稍有考验，但步骤清晰易上手，从备料到出锅大约只需 1 小时。剩余的汤汁用来拌饭或拌面格外鲜美。","tags":["进阶挑战"],"ingredients":[{"name":"肋排","amount":"500 g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"阳江豆豉","amount":"15 g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"蒜蓉","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"姜末","amount":"5 g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"生抽","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"老抽","amount":"3 ml","optional":false,"amountValue":3,"amountUnit":"ml"},{"name":"蚝油","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"白砂糖","amount":"5 g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"生粉","amount":"8 g","optional":false,"amountValue":8,"amountUnit":"g"},{"name":"食用油","amount":"20 ml（不打算淋热油为 10 ml）","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"清水","amount":"30 ml","optional":false,"amountValue":30,"amountUnit":"ml"}],"steps":[{"text":"将排骨用冷水浸泡 10 分钟泡去血水，换水重复 2 次，用厨房纸吸干","group":""},{"text":"将豆豉放入水中浸泡 5 分钟","group":""},{"text":"将所有食材混合（食用油放 10 ml），腌制 8-30 分钟","group":""},{"text":"水开后上锅蒸 18 分钟","group":""},{"text":"焖 2 分钟","group":""},{"text":"锅中倒入 10 ml 热油，加热到 180-200 ℃","group":""},{"text":"均匀撒上葱花和白芝麻，热油浇在撒料上","group":""}],"tips":["豆豉浸泡后稍微剁碎会更入味","蒸制时间随排骨大小调整，以筷子能轻松插入软骨处为准","传统的豉汁排骨不放撒料和淋热油","吃剩的汤汁可以用来拌饭或者拌面"]},
{"id":"chizhizhengbaishan","name":"豉汁蒸白鱔","category":"荤菜","categoryKey":"meat_dish","emoji":"🧃","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/豉汁蒸白鱔/豉汁蒸白鱔.jpeg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"472 大卡","time":"30分钟","servings":"1人份","description":"豉汁蒸白鱔是一道粤式经典蒸菜，豆豉蒜蓉的酱香渗透进鱼肉，口感嫩滑鲜美。白鱔富含优质蛋白和多种不饱和脂肪酸，对身体有滋补作用。操作步骤清晰，但处理生鱼和掌握火候稍有挑战，适合有一定基础的厨友。从备料到上桌大约需要 30 分钟。","tags":["辣","蒸"],"ingredients":[{"name":"白鱔","amount":"250g （约一条小白鱔，已去内脏并切成段）","optional":false,"amountValue":250,"amountUnit":"g"},{"name":"豆豉","amount":"1 汤匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜头","amount":"2 瓣 （剁碎）","optional":false,"amountValue":2,"amountUnit":"瓣"},{"name":"姜","amount":"3 片 （切丝）","optional":false,"amountValue":3,"amountUnit":"片"},{"name":"葱","amount":"1 根 （切段或丝）","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"生抽","amount":"1.5 汤匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"老抽","amount":"0.5 茶匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"糖","amount":"0.5 茶匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"麻油","amount":"0.5 茶匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"生粉","amount":"1 茶匙 （可选，用于腌制）","optional":true,"amountValue":null,"amountUnit":""},{"name":"水","amount":"1 汤匙 （调酱汁）","optional":false,"amountValue":null,"amountUnit":""},{"name":"红椒","amount":"10g （切丝，装饰用）","optional":false,"amountValue":10,"amountUnit":"g"}],"steps":[{"text":"**检查与清洗白鱔**：","group":""},{"text":"购买时已请鱼贩去内脏、刮去黏液并切成约 5 厘米长的段。","group":""},{"text":"回家后检查白鱔，冲洗干净，确保无残留黏液或杂质。","group":""},{"text":"可选：用 3g 盐和 1 茶匙生粉轻搓白鱔段，腌制 5 分钟后冲洗干净，去腥并增加嫩滑口感。","group":""},{"text":"**准备酱汁**：","group":""},{"text":"在小碗中混合 1 汤匙豆豉、2 瓣蒜末、1.5 汤匙生抽、0.5 茶匙老抽、0.5 茶匙糖、0.5 茶匙麻油和 1 汤匙水，搅拌均匀。","group":""},{"text":"若喜欢更浓郁的豉汁，可多加 0.5 汤匙豆豉。","group":""},{"text":"**摆盘**：","group":""},{"text":"将已切好的白鱔段平铺在耐热盘中，尽量不重叠。","group":""},{"text":"将姜丝均匀撒在白鱔上。","group":""},{"text":"将调好的豉汁均匀淋在白鱔上。","group":""},{"text":"**蒸制**：","group":""},{"text":"在蒸锅或电蒸炉中加入水 (500ml)，烧开。","group":""},{"text":"将装有白鱔的盘子放入蒸锅，盖上锅盖。","group":""},{"text":"用中大火蒸约 8-10 分钟 （视白鱔段大小调整时间），至白鱔熟透但不过老 （肉质变白，无血水）。","group":""},{"text":"**装饰与完成**：","group":""},{"text":"蒸好后取出，撒上葱丝和红椒丝 （可选） 作装饰。","group":""},{"text":"可再淋热麻油提升香气。","group":""},{"text":"趁热上桌，搭配白饭享用。","group":""}],"tips":["**注意事项**：","确保白鱔新鲜，购买时选择活鱼，肉质更鲜嫩。","鱼贩切段时可指定长度 （约 5 厘米为宜），方便蒸制和食用。","蒸制时间不宜过长，以免白鱔肉质变韧。","**变种做法**：","可加入辣椒或 XO 酱，增加辣味和层次感。","若喜欢更软嫩的口感，可在腌制时加入米酒。"]},
{"id":"congshaojitui","name":"葱烧鸡腿","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":2,"difficultyText":"★★","calories":"850 大卡","time":"","servings":"1-2人份","description":"葱烧鸡腿是一道只靠鸡腿和大葱两种核心食材就能完成的下饭家常菜。鸡腿肉外焦里嫩，葱香浓郁，做法简单，全程一口锅，新手也能一次成功。蛋白质丰富，搭配米饭尤其合适，适合工作日快手晚餐。","tags":["新手友好"],"ingredients":[{"name":"鸡腿","amount":"2 个（去骨后净肉约 350g）","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"大葱","amount":"1 根（约 100g）","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"小葱","amount":"3-4 根（约 30g）","optional":false,"amountValue":4,"amountUnit":"根"},{"name":"生抽","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"老抽","amount":"5ml（上色用，没有可以全用生抽）","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"蚝油","amount":"10ml（可选，没有就多放 5ml 生抽）","optional":true,"amountValue":10,"amountUnit":"ml"},{"name":"白砂糖","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"料酒","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"盐","amount":"2-3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"白胡椒粉","amount":"1g","optional":false,"amountValue":1,"amountUnit":"g"},{"name":"食用油","amount":"15-20ml","optional":false,"amountValue":20,"amountUnit":"ml"}],"steps":[{"text":"鸡腿去骨：用剪刀从鸡腿大的那头伸进去，贴着骨头把肉剪开，再沿骨剪两下把骨肉分离，最后把骨头整根抽出。比用刀去骨更安全。","group":""},{"text":"去骨后的鸡腿肉切成 2-3cm 的丁。","group":""},{"text":"大葱切厚片（约 0.5cm 厚），小葱切 1cm 长的小段。","group":""},{"text":"鸡腿丁加入 10ml 料酒、5ml 生抽、2g 盐、1g 白胡椒粉抓匀，腌制 10 分钟。","group":""},{"text":"取一个小碗调好料汁：10ml 生抽 + 5ml 老抽 + 10ml 蚝油 + 5g 糖，搅匀备用。","group":""},{"text":"热锅，锅内放入 15-20ml 食用油。","group":""},{"text":"放入姜片和花椒，保持小火炸到姜片微微焦黄、花椒颜色变深。","group":""},{"text":"用漏勺把姜片和花椒捞出丢弃，留底油。","group":""},{"text":"保持中大火，将腌好的鸡腿丁平铺下锅，不要急着翻动。","group":""},{"text":"等待 2-3 分钟让鸡腿丁底部煎出焦壳，再翻炒到所有面都变色、鸡肉完全断生。","group":""},{"text":"下入大葱片，保持中大火翻炒 1 分钟炒出葱香。","group":""},{"text":"倒入调好的料汁，翻炒均匀后盖上锅盖。","group":""},{"text":"等待 2 分钟让料汁和葱香完全融合到鸡肉里。","group":""},{"text":"开盖，下入小葱段和 2g 熟白芝麻（可选），翻炒 5-10 秒即可关火出锅。","group":""}],"tips":["1. 把鸡腿洗干净，用厨房纸吸干表面水分。","2. 从鸡腿较粗的一头找到骨头的末端。","3. 用剪刀尖贴着骨头剪开外层的皮和肉，沿着骨头一侧剪到底。","4. 把鸡腿翻个面，沿骨头的另一侧继续剪。","5. 用手指把肉和骨头之间的连接处剥开。","6. 找到骨头的关节处剪断，把骨头整根抽出。","整个过程不需要用刀，比传统的\"片开剔骨\"法安全很多，新手也能一次成功。","这道菜的核心是葱和鸡腿，但只靠这两样会缺少层次。视频中使用的姜、花椒、蚝油、老抽、白芝麻都是为了让葱香和鸡香更立体。","**极简版**：只用葱 + 鸡腿 + 盐 + 生抽 + 糖也能做出来，但葱香会比较单一。","**推荐版**：加上姜、花椒、蚝油，香味会丰富很多。","**完美版**：再加点老抽上色 + 熟白芝麻点缀，卖相和口感都能上一个台阶。","1. 冷藏保存：密封后放冰箱冷藏，可保存 2 天。","2. 冷冻保存：放凉后分装冷冻，可保存 1 个月。","3. 回热方式：微波炉中火加热 2 分钟，或回锅加一点点水翻炒。"]},
{"id":"daibazhouzi","name":"带把肘子","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":5,"difficultyText":"★★★★★","calories":"1037 大卡","time":"","servings":"1-2人份","description":"带把肘子是陕西大荔的传统名菜，因脚爪形似把柄而得名。成菜肘皮胶粘软糯，肉质酥烂不腻，蘸甜面酱佐葱段食用，咸香醇厚。富含胶原蛋白和优质蛋白质，滋补养颜。制作需去骨、定形、长时间蒸制，对新手有一定挑战，预计整个制作过程约需 3.5 小时。","tags":["甜","进阶挑战"],"ingredients":[{"name":"带脚、爪猪前肘: 一个（大约二斤五两","amount":"1250 克）","optional":false,"amountValue":null,"amountUnit":""},{"name":"红豆腐乳: 1 块","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"甜面酱","amount":"150 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"精盐","amount":"15 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"红酱油","amount":"35 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"白酱油","amount":"25 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"料酒","amount":"25 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜片","amount":"50 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜末","amount":"10 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角","amount":"3 个","optional":false,"amountValue":3,"amountUnit":"个"},{"name":"桂皮","amount":"5 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"葱","amount":"200 克","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"将肘子刮洗干净，肘头朝外、肘把（脚爪）朝里、肘皮朝下放在案板上。","group":""},{"text":"用刀在正中由肘头向肘把沿着腿骨将皮剖开，剔去腿骨两边的肉（三面离肉），底部骨与肉相连，使骨头露出，然后将两节腿骨由中间用刀背（还是用斧头吧）砸断。","group":""},{"text":"肘子放入煮锅煮至七成熟捞出（外观正常，内部淡红色），用干净抹布擦干水，趁热用红酱油涂抹肉皮。","group":""},{"text":"取蒸锅一个，锅底放入八角、桂皮，先将肘把的关节处用手掰断，不伤外皮，再将肘皮朝下装进蒸锅内，装锅时根据肘子体型，将肘把贴住锅边窝着装进锅内，成为圆形。","group":""},{"text":"撒入精盐，用消过毒的干净纱布盖在肉上，再将甜面酱（50 克）、葱（75 克）、红豆腐乳、红酱油、白酱油、姜、蒜等在纱布上抹开，用旺火蒸大约三小时（以蒸烂为准）。","group":""},{"text":"蒸完取出，揭去纱布，扣入盘中，拣去八角，上桌时另带葱段和甜面酱小碟（或将甜面酱抹到肘面上，另带葱段小碟亦可）。","group":""}],"tips":["肘子七成熟要根据实际情况判断，有条件可询问家中长辈。","蒸锅下半放水，上半放肘子，蒸时及时加水防止蒸干。"]},
{"id":"dongguaniangrou","name":"冬瓜酿肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/冬瓜酿肉/冬瓜酿肉成品.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"578 大卡","time":"30分钟","servings":"1-2人份","description":"冬瓜酿肉是一道荤素搭配的家常蒸菜，口感鲜嫩爽滑，肉馅的咸香与冬瓜的清甜相互融合，清爽不腻。猪肉末提供优质蛋白质和必需氨基酸，冬瓜则有助于清热利尿、补充水分。做法简单，即使是新手也能轻松上手，只需稍加练习卷肉技巧即可。从备料到出锅，大约需要 30 分钟。","tags":["进阶挑战"],"ingredients":[{"name":"猪肉末","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"鸡蛋","amount":"1 个（可选,不习惯的人可能会有点腥）","optional":true,"amountValue":1,"amountUnit":"个"},{"name":"冬瓜","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"葱花（一根,约","amount":"20g）","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"胡椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"生抽","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"淀粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"水淀粉","amount":"25g（淀粉 25g,水 50ml）","optional":false,"amountValue":25,"amountUnit":"g"},{"name":"葱姜末（姜","amount":"3-4 片约 30g, 取上面一根葱花中的葱白部分即可）","optional":false,"amountValue":4,"amountUnit":"片"},{"name":"盐","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"}],"steps":[{"text":"冬瓜去皮，切成 25cm 长 3cm 厚的片","group":""},{"text":"将切好的冬瓜放入碗中，放入 15g 盐，将冬瓜抹匀，放置 10 分钟","group":""},{"text":"放置冬瓜的同时，换个碗放入肉末，葱姜末， 5g 盐，淀粉 5g，胡椒粉，生抽，胡椒粉","group":""},{"text":"使用筷子在肉末中进行顺时针搅拌，搅拌到食材颜色没有明显对比（约 2 分钟）","group":""},{"text":"将腌制好的冬瓜（会变软）使用清水洗三遍","group":""},{"text":"拿出 1 片冬瓜片卷起来，并把肉塞进去","group":""},{"text":"放入碟子中摆到碟子的边缘","group":""},{"text":"打入 1 个鸡蛋到中间圆圈处","group":""},{"text":"放入普通铁锅中水烧开后，蒸 15 分钟，盖上锅盖","group":""},{"text":"开盖，取出蒸好的冬瓜酿肉","group":""},{"text":"将冬瓜酿肉碟子的水倒入锅中，放入水淀粉，加入 50ml 清水倒入锅中烧开","group":""},{"text":"淋到冬瓜酿肉上","group":""}],"tips":["操作时，拿出冬瓜酿肉时注意碟子很烫，小心操作。","参考资料：b站视频"]},
{"id":"douchilingyuyoumaicai","name":"豆豉鲮鱼油麦菜","category":"荤菜","categoryKey":"meat_dish","emoji":"🐟","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/豆豉鲮鱼油麦菜/豆豉鲮鱼油麦菜成品.jpg","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"416 大卡","time":"","servings":"2人份","description":"豆豉鲮鱼油麦菜是一道咸香下饭的快手家常小炒，源于粤式罐头菜肴，油麦菜清脆、鲮鱼酥香。荤素搭配，富含蛋白质和膳食纤维。做法简单，对新手十分友好，一般十五分钟即可完成。","tags":["新手友好"],"ingredients":[{"name":"油麦菜","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"鲮鱼罐头","amount":"1 罐（250g 上下）","optional":false,"amountValue":250,"amountUnit":"g"},{"name":"蒜","amount":"4 瓣","optional":false,"amountValue":4,"amountUnit":"瓣"},{"name":"生抽","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"白糖","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"食用油","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"}],"steps":[{"text":"**食材处理**：","group":""},{"text":"油麦菜洗净后切段","group":""},{"text":"鲮鱼罐头打开后，把鲮鱼主刺去除，切成小段后备用","group":""},{"text":"大蒜切成末","group":""},{"text":"**炒制过程**：","group":""},{"text":"锅热倒入食用油，油热后加入洗净的油麦菜，炒到萎蔫出水后盛出备用，倒掉炒制出的水分","group":""},{"text":"重新热锅后，加入鲮鱼罐头中的油，放入蒜末煸香","group":""},{"text":"蒜末煸香后加入鲮鱼罐头中的豆豉，翻拌后加入切碎的鲮鱼块，再次翻拌","group":""},{"text":"翻拌均匀后加入油麦菜，加入生抽和糖调味","group":""},{"text":"调味加入后简单翻拌即可出锅装盘","group":""}],"tips":["**注意事项**：","1. 鲮鱼罐头本身带味道，加入生抽后够味，无需下盐"]},
{"id":"fanqiehongjiang","name":"番茄红酱","category":"荤菜","categoryKey":"meat_dish","emoji":"🍆","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"1955 大卡","time":"","servings":"1-2人份","description":"这款意式风味酱料香浓可口，蔬菜与牛肉的搭配带来丰富口感。它富含蛋白质和多种维生素，营养均衡。制作过程稍有繁琐，需要一些烹饪基础，例如炒出颗粒感的牛肉和控火慢煮。从备料到完成约需一小时，一次可多做一些冷冻保存，随取随用十分方便。","tags":["进阶挑战"],"ingredients":[{"name":"碎牛肉","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"蒜瓣","amount":"2 个","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"胡萝卜 半根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"芹菜 一根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"洋葱 半个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"橄榄油","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"糖","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"食盐","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"黑胡椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"番茄酱","amount":"300g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"牛奶","amount":"300ml","optional":false,"amountValue":300,"amountUnit":"ml"}],"steps":[{"text":"将胡萝卜、芹菜、洋葱切碎，蒜瓣切片。","group":""},{"text":"加入 10ml 橄榄油，热油下锅蔬菜，大火翻炒开始略微变色后盛出。","group":""},{"text":"锅内加油 10ml，加蒜翻炒 10 秒，加入碎牛肉、糖、盐、胡椒粉和香料将牛肉炒脆（有颗粒感）。","group":""},{"text":"加入炒好的蔬菜们和番茄酱继续翻炒，搅拌均匀。","group":""},{"text":"分多次缓缓倒入牛奶，中小火煮 30 分钟，完成。","group":""}],"tips":["**考虑各个品牌的番茄酱内含盐量不同，建议在炒牛肉时少放盐，煮的时候尝一下再调味**","**煮酱料期间请搅动，以免粘锅。如果酱料变粘稠就可以出锅啦！**","可根据个人口味，将碎牛肉替换成一半碎猪肉一半碎牛肉，牛奶替换成鸡汤或饮用水。"]},
{"id":"fenzhengrou","name":"粉蒸肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"1606 大卡","time":"90分钟","servings":"1-2人份","description":"粉蒸肉是一道经典中式蒸菜，香味浓郁，口感软糯，属于广泛流传的家常风味。五花肉提供优质蛋白质和脂肪，搭配土豆等根茎蔬菜，营养均衡。此菜适合有一定烹饪经验的人士制作，从准备到完成大约需要 90 分钟。","tags":["辣","蒸","进阶挑战"],"ingredients":[{"name":"五花肉","amount":"250g","optional":false,"amountValue":250,"amountUnit":"g"},{"name":"蒸肉米粉","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"生抽","amount":"7.5ml","optional":false,"amountValue":7.5,"amountUnit":"ml"},{"name":"老抽","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"料酒","amount":"7.5ml","optional":false,"amountValue":7.5,"amountUnit":"ml"},{"name":"郫县豆瓣酱","amount":"5g（可选）","optional":true,"amountValue":5,"amountUnit":"g"},{"name":"姜末","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"蒜末","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"白砂糖","amount":"2.5g","optional":false,"amountValue":2.5,"amountUnit":"g"},{"name":"土豆或南瓜","amount":"150g","optional":false,"amountValue":150,"amountUnit":"g"},{"name":"蒸锅用水","amount":"1000ml","optional":false,"amountValue":1000,"amountUnit":"ml"}],"steps":[{"text":"将五花肉洗净，切成长约 5cm、宽约 3cm、厚度约 0.5cm 的肉片","group":""},{"text":"将姜、蒜切成颗粒直径不大于 1mm 的细末","group":""},{"text":"取一大碗，放入切好的五花肉、15ml 生抽、10ml 老抽、15ml 料酒、10g 郫县豆瓣酱、10g 姜末、10g 蒜末、5g 白砂糖","group":""},{"text":"用筷子搅拌均匀后，盖上保鲜膜，室温(20°C - 25°C)静置腌制 30 分钟","group":""},{"text":"腌制完成后，加入 100g 蒸肉米粉，继续翻拌 2 分钟，确保每片肉都均匀裹粉","group":""},{"text":"土豆去皮，切片厚度控制在 0.8cm，片面积约为 5cm x 5cm，重量控制在 300g","group":""},{"text":"在直径 20cm 的深碗底部铺满土豆片，尽量无重叠","group":""},{"text":"将拌好粉的五花肉均匀铺在土豆片上，压实","group":""},{"text":"蒸锅中加入 2000ml 清水，开火加热至水面持续冒泡(100°C)","group":""},{"text":"将装好食材的碗放入蒸锅内，盖好锅盖","group":""},{"text":"保持中火蒸 60 分钟（火力保持在可持续沸腾的程度，约 600W 热功率）","group":""},{"text":"时间结束后，用筷子插入肉块中央，若能轻松穿透并无明显阻力，则表明蒸熟","group":""},{"text":"若未达到此状态，则继续加热 10 - 15 分钟，直至肉质软烂，油脂渗出","group":""},{"text":"取出盛盘，即可食用","group":""}],"tips":["如需自制米粉，可将大米 150g 放入锅中，中小火炒至微黄色（约 8 分钟），再加入干辣椒 1g、花椒 1g、八角 0.5g，炒香后用料理机打碎，过筛备用","蒸制期间如水量低于锅底高度 1cm，应立即补充 500ml 热水（90°C 以上），以维持蒸汽充足"]},
{"id":"fururou","name":"腐乳肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":5,"difficultyText":"★★★★★","calories":"1190 大卡","time":"","servings":"1-2人份","description":"这是一道经典的江南家常菜，五花肉与红腐乳同炖，色泽红亮如琥珀，肉质酥烂到入口即化，咸甜交织的酒香与豆香在舌尖层层展开。富含优质蛋白质和 B 族维生素，经慢火煨煮后更易消化。制作流程需要耐心把控火候和收汁，对新手来说有一定挑战，预计制作时长约 1 小时。","tags":["进阶挑战"],"ingredients":[{"name":"带皮五花肉","amount":"400 g","optional":false,"amountValue":400,"amountUnit":"g"},{"name":"红腐乳","amount":"30 g（约 2 块）","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"腐乳汁","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"冰糖","amount":"25 g","optional":false,"amountValue":25,"amountUnit":"g"},{"name":"老抽","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"料酒","amount":"15 ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"葱白","amount":"15 g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"葱花","amount":"5 g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"生姜","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"清水","amount":"500 ml","optional":false,"amountValue":500,"amountUnit":"ml"},{"name":"食用油","amount":"10 ml","optional":false,"amountValue":10,"amountUnit":"ml"}],"steps":[{"text":"五花肉切成长宽 2.5 cm 的小块","group":""},{"text":"冷水放料酒姜片，五花肉放入开火慢慢加入到水沸腾后捞出","group":""},{"text":"玫瑰腐乳块和腐乳汁碾成泥，加冰糖、老抽调成酱汁","group":""},{"text":"热锅冷油爆香葱姜，下肉块煸到金黄","group":""},{"text":"倒入腐乳酱炒匀加热水焖煮","group":""},{"text":"小火慢炖 40 分钟","group":""},{"text":"大火收汁，看到汤汁冒浓稠鱼眼泡时关火","group":""}],"tips":["建议用单晶冰糖","腐乳自带咸鲜，不用额外放盐","大火收汁时要不断晃动锅体避免粘底","参考资料：【步骤图】腐乳肉的做法_腐乳肉的做法步骤_菜谱_下厨房"]},
{"id":"ganbianzaiji","name":"干煸仔鸡","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/干煸仔鸡/干煸仔鸡成品.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"1300 大卡","time":"","servings":"1-2人份","description":"这是一道源自北大食堂、甜辣风味的创新川菜，鸡肉先腌后炸，外酥里嫩，土豆香糯，青椒脆爽，裹满红亮的甜辣酱汁，咸甜微辣十分开胃。富含蛋白质、碳水化合物及维生素。制作涉及油炸和酱汁熬制，对新手稍有挑战，但按步骤操作即可成功，全程约需 1 小时。","tags":["辣","进阶挑战"],"ingredients":[{"name":"鸡腿肉","amount":"400g","optional":false,"amountValue":400,"amountUnit":"g"},{"name":"土豆","amount":"200g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"青椒","amount":"60g","optional":false,"amountValue":60,"amountUnit":"g"},{"name":"蒜瓣","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"鸡精","amount":"3g （可选）","optional":true,"amountValue":3,"amountUnit":"g"},{"name":"胡椒粉","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"生抽","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"老抽","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"料酒","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"淀粉","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"郫县红油豆瓣酱","amount":"40g","optional":false,"amountValue":40,"amountUnit":"g"},{"name":"白糖","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"花椒碎","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"}],"steps":[{"text":"鸡腿去骨（如使用鸡腿排可忽略此步骤），鸡腿肉用刀背砸一砸，切成 2cm 的块。","group":""},{"text":"鸡腿肉中加入盐、鸡精（可选）、胡椒粉、生抽、老抽、料酒，抓拌至粘手时加入淀粉拌匀，加入食用油防止粘连，腌制 30 分钟。","group":""},{"text":"土豆去皮，切成 2cm 的块，沸水煮 5 分钟后捞出，控干水分，防止油炸时爆锅。","group":""},{"text":"青椒去籽，切成 2cm 小片，放在笊篱中备用。","group":""},{"text":"锅中加入宽油（根据锅的形状，能没过食材即可），油温烧至 180℃ 时，下入土豆块炸 3 分钟后捞出。","group":""},{"text":"待油温再次升高到 180℃时，下入鸡块炸 2 分钟后捞出。","group":""},{"text":"待油温再次升高到 180℃时，下入鸡块复炸 1 分钟后捞出。","group":""},{"text":"待油温再次升高到 180℃时，下入土豆块复炸 1 分钟后，将锅中的油和土豆块经过笊篱过滤倒出，让笊篱上的青椒片断生。","group":""},{"text":"锅中加入 5ml 食用油，小火煸炒蒜瓣至发黄，下入红油豆瓣酱煸炒出香，下入白糖炒融化，下入花椒碎，加 40ml 清水，不停搅拌至酱汁粘稠。","group":""},{"text":"下入炸好的鸡块、土豆块、青椒片，搅拌均匀后出锅。","group":""}],"tips":["不舍得使用宽油油炸的话，可改用更少的油煎鸡块和土豆块。会增长用时，部分影响口感，但不会影响总体味道。","参考资料：北大餐饮中心官方资讯"]},
{"id":"gongbaojiding","name":"宫保鸡丁","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/宫保鸡丁/宫保鸡丁.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"1790 大卡","time":"1.5小时","servings":"1人份","description":"这道川味名菜以糊辣荔枝味见长，小酸甜中透着干辣椒与花椒的香气，鸡丁嫩滑、花生酥脆，口感层次丰富。富含优质蛋白和不饱和脂肪酸，开胃下饭。做法分成简易和进阶两版，对新手比较友好，提前规划好腌制时间即可。从备料到出锅大约需要 1.5 小时。","tags":["辣","进阶挑战"],"ingredients":[{"name":"手枪腿（或者鸡胸脯肉）","amount":"1 支（约 350g）","optional":false,"amountValue":1,"amountUnit":"支"},{"name":"大葱","amount":"1 根（约 180g）","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"熟花生","amount":"150g","optional":false,"amountValue":150,"amountUnit":"g"},{"name":"姜片","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"干辣椒（或者二荆条）","amount":"10g（若选择二荆条，则需要大约 4 支）","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"生抽酱油","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"白糖","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"盐","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"植物油","amount":"20g","optional":false,"amountValue":20,"amountUnit":"g"},{"name":"淀粉","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"料酒","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"老抽酱油","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"花椒","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"香醋","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"鸡精","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"芝麻油","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"淀粉（用以勾芡）","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"豆瓣酱","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"莴笋","amount":"约 250g","optional":false,"amountValue":250,"amountUnit":"g"},{"name":"油泼辣子","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"}],"steps":[{"text":"手枪腿用剪刀去骨，鸡肉面用刀背拍打一遍，切条后切至 1.5cm 见方肉丁；泡于清水 10 分钟，捞出控干备用（若是鸡胸脯肉，则可以直接进行切丁以及之后的动作）","group":"简易版本"},{"text":"取大葱葱绿与姜片 5g 于碗中，倒入 50g 开水备用；葱白切 1.5cm 圆粒备用；取花生放入微波炉高火 5 分钟焙干备用","group":"简易版本"},{"text":"鸡丁中加入盐 2g，老抽酱油 5g，料酒 15g，淀粉 15g 搅拌均匀，至微微发干；缓慢加入部分葱姜水，搅拌鸡丁至粘手；保鲜膜密封，放入冰箱腌制 1 小时","group":"简易版本"},{"text":"干辣椒切段；起锅，大火烧热转小火；放入干辣椒焙干至微微发糊，捞起备用；花椒焙干至有香味，捞起备用","group":"简易版本"},{"text":"转大火，倒入 20g 植物油，7 成热（竹筷子起泡）下入鸡丁，煎至上面开始发白，用锅铲翻面，煎 30s 后翻炒均匀","group":"简易版本"},{"text":"下入葱粒翻炒，加入余下葱姜水不够 100g 再加一点清水（务必是热水）；盖上锅盖，转中小火焖 2 分钟；","group":"简易版本"},{"text":"转大火，下入熟花生，干辣椒和花椒；加入鸡精 2g，香醋 5g，白糖 2g，翻炒均匀；","group":"简易版本"},{"text":"淀粉 10g 加 50g 清水调成水淀粉，加入锅中，翻炒均匀，收汁到自己想要的浓度","group":"简易版本"},{"text":"关火，淋入芝麻油 10g，即可出锅","group":"简易版本"},{"text":"莴笋去皮切至 1cm 见方的小块，备用；","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"二荆条切成 1cm 长段；","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"手枪腿用剪刀去骨，鸡肉面用刀背拍打一遍，切条后切至 1.5cm 见方肉丁；泡于清水 10 分钟，捞出控干备用（若是鸡胸脯肉，则可以直接进行切丁以及之后的动作）；","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"取大葱葱绿与姜片 5g 于碗中，倒入 50g 开水备用；葱白切 1.5cm 圆粒备用","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"鸡丁中加入盐 2g，老抽酱油 5g，料酒 15g，淀粉 15g 搅拌均匀，至微微发干；缓慢加入部分葱姜水，搅拌鸡丁至粘手；保鲜膜密封，放入冰箱腌制 1 小时","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"转中火，倒入 20g 植物油，放入生花生翻炒至其表面微微焦糊，捞起花生但是油留在锅内；","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"继续加热，7 成热（竹筷子起泡）下入鸡丁，放入豆瓣酱，翻炒大概 1 分钟；","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"加入备好的莴笋丁，继续翻炒 1 分钟；","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"下入葱粒翻炒，加入余下葱姜水不够 100g 再加一点清水（务必是热水）；加入二荆条段；盖上锅盖，转中小火焖 2 分钟；","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"转大火，下入先前捞起来备用的花生，花椒；加入鸡精 2g，香醋 5g，白糖 2g，翻炒均匀；","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"淀粉 10g 加 50g 清水调成水淀粉，加入锅中，翻炒均匀，收汁到自己想要的浓度","group":"稍加复杂但是更加令人垂涎欲滴的版本"},{"text":"关火，淋入芝麻油 10g 与油泼辣子 5g 再翻炒 10s，即可出锅","group":"稍加复杂但是更加令人垂涎欲滴的版本"}],"tips":["辣椒依据个人口味酌量添加，怕辣可去籽；"]},
{"id":"gulurou","name":"咕噜肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"673 大卡","time":"40分钟","servings":"1-2人份","description":"咕噜肉是一道经典粤式家常菜，酸甜开胃、外酥里嫩，菠萝的果香让肉块吃起来格外清爽解腻。猪肉提供优质蛋白质，青椒和菠萝则补充维生素与膳食纤维。这道菜的难点在于掌握炸肉的火候，对新手略有挑战，但只要按步骤操作便能成功。从腌制到出锅，全程大约需要 40 分钟，很适合为家人做一道下饭快菜。","tags":["汤","进阶挑战"],"ingredients":[{"name":"1 汤匙","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"1 茶匙","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"梅头猪肉","amount":"100g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"青椒","amount":"25g","optional":false,"amountValue":25,"amountUnit":"g"},{"name":"罐头菠萝片","amount":"75g","optional":false,"amountValue":75,"amountUnit":"g"},{"name":"盐","amount":"1/4 茶匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"茄汁","amount":"4 汤匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"白醋","amount":"2 茶匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜蓉","amount":"1 汤匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽","amount":"1/2 茶匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"生粉","amount":"2 1/2 茶匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"白砂糖","amount":"2 汤匙","optional":false,"amountValue":null,"amountUnit":""},{"name":"水","amount":"200 毫升","optional":false,"amountValue":null,"amountUnit":""}],"steps":[{"text":"将梅头猪肉（100 克）洗净，然后用厨房纸抹干水份，将猪肉切成比想要的成品小一圈的大小。","group":""},{"text":"用盐（1/2 茶匙）腌制梅头猪肉 20 分钟。","group":""},{"text":"将青椒（25 克）切碎。","group":""},{"text":"将菠萝片（75 克）切件。","group":""},{"text":"在碗中加入茄汁（4 汤匙）﹑白醋（2 茶匙）﹑蒜蓉（1 汤匙）﹑生抽（½ 茶匙）﹑生粉（2½ 茶匙）﹑白砂糖（2 汤匙）﹑盐（¼ 茶匙）和水（200 毫升），拌匀成酱汁。","group":""},{"text":"将梅头猪肉粒沾上生粉（6 汤匙）。","group":""},{"text":"加入油（500 毫升）中火加热。","group":""},{"text":"将梅头猪肉粒放至锅里中火炸 5 分钟，然后盛起。","group":""},{"text":"加入梅头猪肉粒，再大火翻炸 1 分钟。","group":""},{"text":"加入油（1 茶匙）和酱汁，中火加热 3 分钟。","group":""},{"text":"加入青椒和菠萝，大火加热 2 分钟。","group":""},{"text":"将已炸好的梅头猪肉粒与酱汁拌匀即可。","group":""}],"tips":["想让肉更有层次可以在生粉中加鸡蛋，炸出来会更香脆"]},
{"id":"guangshiluoboniunan","name":"广式萝卜牛腩","category":"荤菜","categoryKey":"meat_dish","emoji":"🥩","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/广式萝卜牛腩/广式萝卜牛腩.webp","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"483 大卡","time":"2.5小时","servings":"3-4人份","description":"这是一道广式家常炖菜，牛腩软烂入味，萝卜吸饱汤汁后清甜浓郁，整体酱香回甘。富含优质蛋白和膳食纤维，开胃助消化。制作步骤稍多但难度适中，新手按部就班也能成功。预计从头到尾大约需要 2.5 小时完成。","tags":["辣","进阶挑战"],"ingredients":[{"name":"牛腩","amount":"500g","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"白萝卜","amount":"1 根","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"姜片","amount":"8 片","optional":false,"amountValue":8,"amountUnit":"片"},{"name":"蒜瓣","amount":"5 片","optional":false,"amountValue":5,"amountUnit":"片"},{"name":"葱结 一把","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"桂皮","amount":"1 小块","optional":false,"amountValue":null,"amountUnit":""},{"name":"干辣椒","amount":"2 个","optional":false,"amountValue":2,"amountUnit":"个"},{"name":"香叶","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"南乳","amount":"1 块","optional":false,"amountValue":1,"amountUnit":"块"},{"name":"柱侯酱","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"蚝油","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"酱油","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"冰糖","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"老抽","amount":"15g","optional":false,"amountValue":15,"amountUnit":"g"}],"steps":[{"text":"萝卜滚到切块备用","group":"开始制作"},{"text":"牛腩整块焯水，加入 2 片姜和一把葱结，等水开之后煮 5-10 分钟，然后捞出切件","group":"开始制作"},{"text":"将牛腩切块，切成自己喜欢的大小（牛腩焯过水，待会儿焖的时候基本不会缩水了，大块的会焖相对就一点的时间）","group":"开始制作"},{"text":"准备焖牛腩的酱料，将南乳、柱侯酱、酱油、蚝油、糖、盐按上面的量调和（冰糖刚刚没了换成了白糖）","group":"开始制作"},{"text":"热锅下油，将姜蒜爆香，放入牛腩，炒至干身，加入调好的酱料，炒香，如果喜欢色泽浓一点的可以加一点老抽润色一下","group":"开始制作"},{"text":"调料充分混合之后倒入热水","group":"开始制作"},{"text":"将牛腩换到汤锅中，放入桂皮、八角、香叶和干辣椒，焖大概 2 个小时","group":"开始制作"},{"text":"牛腩焖到半软之后加入白萝卜继续焖 30 分钟","group":"开始制作"},{"text":"等到萝卜焖软之后就完成，一锅浓香的萝卜牛腩就完成了","group":"开始制作"}],"tips":[]},
{"id":"guizhoulaziji","name":"贵州辣子鸡","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/贵州辣子鸡/贵州辣子鸡.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"1441 大卡","time":"","servings":"1-2人份","description":"贵州辣子鸡是贵州地区的经典家常菜，以糍粑辣椒和多种香料烹制而成，鸡肉香糯软烂，土豆绵密入味，整体风味香辣浓郁。鸡肉富含优质蛋白质，搭配土豆等配菜，营养均衡。这道菜步骤较多，对新手有一定挑战，但按部就班也能成功。从备料到出锅，预计需要 1.大约 5 小时。","tags":["辣","炸","进阶挑战"],"ingredients":[{"name":"鸡三到四个人的量是四斤，人多可以依次累加","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"啤酒半瓶","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"姜手指头大小两个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"糍粑辣椒","amount":"500g，会是拳头大小两坨","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"蒜苗三根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香叶","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"大蒜两个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"土豆两个","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"菜籽油两斤，开始炸鸡会用很多","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"老抽","amount":"20 ml","optional":false,"amountValue":20,"amountUnit":"ml"}],"steps":[{"text":"在锅中加入和锅一半高度的油，将切成长条的土豆先炸至表面金黄然后捞出备用，等油温上至烤手时候将切好的鸡块放入锅中炸，并放入切好的生姜片和花椒","group":""},{"text":"刚开始炸鸡的时候，油是浑浊的，因为鸡块里面有水的原因，等到油炸至清澈，鸡块就炸好了，然后捞出备用","group":""},{"text":"现在锅里面的油可以捞三分之一出来，现在用不到这么多的油","group":""},{"text":"将锅中剩余的油加热，加入糍粑辣椒，豆瓣酱，生姜片，炒出红油状，将炸好的鸡块翻炒均匀","group":""},{"text":"等到鸡块都上色，加入老抽，倒入啤酒，啤酒一定要盖过鸡块，加上香叶盖上盖，闷十分钟，期间间隔翻炒","group":""},{"text":"然后加入土豆条，大蒜（不用切，一颗一颗的最好），然后再闷 20 分钟","group":""},{"text":"最后加入酒糟翻炒均匀再加入切好的蒜苗，就可以出锅了","group":""}],"tips":["操作时，需要注意翻炒，因为糍粑辣椒会糊掉"]},
{"id":"guilinshibaniang","name":"桂林十八酿","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/桂林十八酿/arch.png","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"468 大卡","time":"","servings":"1人份","description":"桂林传统酿菜系列，将调好味的猪肉、虾滑等馅料酿入青椒、苦瓜、田螺、茄子等十多种中空食材中，煎焖成菜，一菜一味，鲜香多汁，口感软嫩或弹牙，属于浓郁的地方家常风味。馅料提供优质蛋白质，搭配多种蔬菜，富含维生素与膳食纤维，营养较为均衡。制作步骤需要逐一填馅和掌控火候，稍需耐心，但操作逻辑简单，厨艺新手也能尝试，预计全部完成约需 1.5 小时。","tags":[],"ingredients":[],"steps":[{"text":"**青椒酿**：青椒去籽挖空 → 塞入猪肉馅或虾滑 → 煎至虎皮色 → 酱汁焖煮","group":"核心思路"},{"text":"**田螺酿**：田螺焯水取肉 → 螺肉与猪肉剁碎混合 → 塞回螺壳 → 紫苏薄荷焖煮","group":"核心思路"},{"text":"**猪肉馅**：最基础通用的选择，肥瘦 3:7 口感最佳","group":"核心思路"},{"text":"**虾滑馅**：鲜甜弹牙，青椒酿里常用","group":"核心思路"},{"text":"**螺肉猪肉混合馅**：田螺酿的灵魂，螺肉与猪肉 1:1，加紫苏薄荷","group":"核心思路"},{"text":"**混合馅**：猪肉 + 虾滑混搭，鲜甜与油脂香兼得","group":"核心思路"}],"tips":["青椒酿 — 青椒酿肉 / 虾滑酿青椒（fork 版本）","田螺酿 — 螺肉猪肉 1:1，配紫苏薄荷"]},
{"id":"helandouchaolachang","name":"荷兰豆炒腊肠","category":"荤菜","categoryKey":"meat_dish","emoji":"🫘","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/荷兰豆炒腊肠/1.png","hasImage":true,"difficulty":2,"difficultyText":"★★","calories":"606 大卡","time":"","servings":"1人份","description":"荷兰豆炒腊肠是一道清爽咸香的家常小炒，腊肠的油脂润着翠绿的荷兰豆，口感脆嫩不腻。荷兰豆富含优质蛋白质和多种维生素，有助于增强机体抗病能力。做法简单，几乎不需要刀工，初学者也能快速上手，从备料到出锅大约只需 15 分钟。","tags":["新手友好"],"ingredients":[{"name":"荷兰豆大约","amount":"50 个","optional":false,"amountValue":50,"amountUnit":"个"},{"name":"腊肠约","amount":"100 g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"食用油","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"生抽","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"}],"steps":[{"text":"把荷兰豆去掉蒂，有时间的也可以同时把尾部去掉","group":""},{"text":"买腊肠之前可以问老板是生的还是熟的，如果是生的，需要提前蒸一下，如果是熟的可以直接使用","group":""},{"text":"把荷兰豆清洗一下，然后焯一下水，大概 45s，荷兰豆焯至变色即可，捞出过凉水备用","group":""},{"text":"热锅，锅内放入大约 10ml 食用油。等待 10 秒让油温升高","group":""},{"text":"放入腊肠，保持翻炒至腊肠*微微卷边*，注意这里一定要**保持小火**，小到不能小的那种，不然容易糊","group":""},{"text":"放入荷兰豆，转为中大火，翻炒 30s 放入生抽，接着再翻炒 20-30s 即可","group":""}],"tips":["在制作过程中没有放盐，是因为腊肠本身会有一些味道，同时生抽也会有一些咸味。","腊肠虽然味道不错，但属于不太健康的食物，建议少放。"]},
{"id":"heijiaoniuliu","name":"黑椒牛柳","category":"荤菜","categoryKey":"meat_dish","emoji":"🥩","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/黑椒牛柳/黑椒牛柳.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"216 大卡","time":"","servings":"1人份","description":"黑椒牛柳是一道广受欢迎的家常小炒，黑椒风味浓郁，牛柳嫩滑，搭配甜脆的洋葱和彩椒，荤素均衡，口味老少咸宜。牛肉富含优质蛋白和铁，彩椒和洋葱能补充多种维生素。这道菜对新手十分友好，从备料到出锅，通常一小时以内就能完成。","tags":["进阶挑战"],"ingredients":[{"name":"牛肉量","amount":"份数 * 100 克 （视就餐者胃容量和锅容量酌情增减）","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐量","amount":"份数 * 1 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"淀粉","amount":"份数 * 3 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"黑椒腌料","amount":"参照所购商品的说明按比例腌制","optional":false,"amountValue":null,"amountUnit":""},{"name":"黑胡椒粉","amount":"份数 * 1 克（实际上是随便撒）","optional":false,"amountValue":null,"amountUnit":""},{"name":"花生油","amount":"份数 * 10ml （实际上油量是依据菜量变动的，如对牛肉的量有增减请按对应比例变动）","optional":false,"amountValue":10,"amountUnit":"ml"}],"steps":[{"text":"将牛肉切条，长度最好控制在 8 厘米以下，厚度约 5-10 毫米，宽度约 1 厘米（要求不严格）","group":""},{"text":"利用腌料腌制牛肉，混合均匀后静置，用量与时间请参照商品说明，可以延长不能缩短。","group":""},{"text":"如果使用液态腌料，可以在腌制结束前三分钟撒一层黑胡椒粉，然后再加入淀粉，再次混合均匀后静置 20 分钟。","group":""},{"text":"开火，热锅，加入花生油。","group":""},{"text":"当能看到锅里的油冒出一丝烟时，放入牛肉，翻炒。","group":""},{"text":"开中火偏大，翻炒 2 分钟至牛肉外表变色（即不出现明显血色，有血色部分说明翻炒不到位）（此处应小心油滴溅射）。","group":""},{"text":"放入洋葱和菜椒，翻炒 2 分钟。","group":""},{"text":"加入盐，再次撒一份黑胡椒粉，翻炒 30 秒，搅拌均匀。","group":""},{"text":"观察洋葱已经变软即可关火，出锅，盛盘。","group":""}],"tips":[]},
{"id":"hongshaojichi","name":"红烧鸡翅","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"1016 大卡","time":"40分钟","servings":"3-4人份","description":"红烧鸡翅是一道家常下饭菜，咸鲜带甜、色泽红亮，肉质嫩滑易脱骨。鸡翅富含优质蛋白质与胶原蛋白，营养好吸收。制作难度适中，新手按步骤操作也能顺利掌握，从备料到出锅大约需要 40 分钟。","tags":["辣"],"ingredients":[{"name":"新鲜鸡翅","amount":"500g（约 8-10 个，单个鸡翅约 50-60g）","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"姜片","amount":"4-5 片（约 10g，切片厚度约 2mm）","optional":false,"amountValue":5,"amountUnit":"片"},{"name":"葱段","amount":"2-3 段（约 15g，每段长度约 3cm）","optional":false,"amountValue":3,"amountUnit":"段"},{"name":"大蒜","amount":"3-4 瓣（约 15g）","optional":false,"amountValue":4,"amountUnit":"瓣"},{"name":"香叶","amount":"1 片","optional":false,"amountValue":1,"amountUnit":"片"},{"name":"八角","amount":"1 个","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"干辣椒","amount":"2 个（可选，约 5g，不吃辣可省略）","optional":true,"amountValue":2,"amountUnit":"个"},{"name":"冰糖","amount":"15g（颗粒状冰糖）","optional":false,"amountValue":15,"amountUnit":"g"},{"name":"黄酒或料酒","amount":"35ml","optional":false,"amountValue":35,"amountUnit":"ml"},{"name":"生抽","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"老抽","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"白糖","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"胡椒粉","amount":"1g","optional":false,"amountValue":1,"amountUnit":"g"},{"name":"白芝麻","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"小葱花","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"食用油","amount":"10-15ml","optional":false,"amountValue":15,"amountUnit":"ml"}],"steps":[{"text":"将鸡翅洗净。用刀在鸡翅厚处划三刀，背面扎一刀，便于入味。","group":""},{"text":"如果鸡翅不新鲜，可在打完花刀之后用姜水泡 10-20 分钟。","group":""},{"text":"将 10g 姜片（3-4 片）、15g 葱段（2-3 段）备好；3-4 瓣大蒜（约 15g）用刀拍散（无需剁碎）；1 片香叶、1 个八角、2 个干辣椒（可选）整理好备用。","group":""},{"text":"起锅开火，锅中加入清水没过所有鸡翅，冷水下锅放入处理好的鸡翅，加入 20ml 黄酒或料酒、2 片姜片（约 5g），开大火烧至沸腾，沸腾后保持大火继续煮 2-3 分钟，撇去浮沫。","group":""},{"text":"煮好后将鸡翅捞出，用温水清洗 2 遍，彻底去除血沫，控干水分备用。","group":""},{"text":"另起锅，开火烧热后放入 10-15ml 食用油。","group":""},{"text":"待油温至 5 成热，加入 15g 冰糖，开大火将冰糖熬至完全融化，冰糖融化变色后转小火，继续炒至冰糖呈枣红色，立即放入控干水分的鸡翅，快速翻炒 1-2 分钟，使每只鸡翅均匀裹上糖色。","group":""},{"text":"加入准备好的 1 片香叶、1 个八角、2 个干辣椒（可选）、剩下的 2 片姜片（约 5g）、15g 葱段、拍散的大蒜，继续煸炒 30 秒至香料香味完全释放。","group":""},{"text":"沿锅边淋入 15ml 料酒或黄酒，15ml 生抽，快速翻炒 10 秒。","group":""},{"text":"加入温水（水温约 50-60℃），水量以稍微没过所有鸡翅为准。","group":""},{"text":"加入 5ml 老抽、3g 盐、2g 白糖、1g 胡椒粉，用炒勺轻轻搅拌均匀。","group":""},{"text":"盖上锅盖，开中火烧煮 7-8 分钟。","group":""},{"text":"打开锅盖，用筷子将锅中的香叶、八角、姜片、葱段、大蒜捡出丢弃。","group":""},{"text":"转大火，保持不断翻炒，将汤汁烧至粘稠状态（约 1-2 分钟）。","group":""},{"text":"关火，将鸡翅盛入盘中，淋上锅中剩余的粘稠汤汁。","group":""},{"text":"最后撒上 3g 白芝麻和 5g 小葱花，完成制作。","group":""}],"tips":["如果闻着有腥味，可以增加一倍香料用量。"]},
{"id":"hongshaozhuti","name":"红烧猪蹄","category":"荤菜","categoryKey":"meat_dish","emoji":"🥓","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/红烧猪蹄/红烧猪蹄.jpg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"639 大卡","time":"1小时","servings":"3-4人份","description":"红烧猪蹄是一道汤汁浓郁、肉质软糯的经典家常菜，咸香甜美，极为下饭。猪蹄富含胶原蛋白和蛋白质，营养丰富。这道菜对新手有一定挑战，但借助高压锅可以简化流程，有一定烹饪基础更易上手。从备料到完成大约需要 1 小时。","tags":["进阶挑战"],"ingredients":[{"name":"猪蹄：2~3 根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"食用油：30ml","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香叶","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"姜","amount":"5 片","optional":false,"amountValue":5,"amountUnit":"片"},{"name":"葱半根","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"桂皮","amount":"1 块","optional":false,"amountValue":1,"amountUnit":"块"},{"name":"冰糖","amount":"7-8 粒","optional":false,"amountValue":8,"amountUnit":"粒"},{"name":"料酒","amount":"30 ml","optional":false,"amountValue":30,"amountUnit":"ml"},{"name":"生抽","amount":"20 ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"老抽","amount":"20 ml","optional":false,"amountValue":20,"amountUnit":"ml"},{"name":"盐","amount":"8 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角","amount":"4 个","optional":false,"amountValue":4,"amountUnit":"个"}],"steps":[{"text":"冷水锅中放入热心摊主剁好的猪蹄，加入 20 ml 料酒与葱姜，煮 15 分钟去掉血腥","group":"开始制作"},{"text":"热锅冷油，倒入 30ml 食用油，放入 7-8 粒冰糖，开小火，熬成糖色，期间用锅铲把冰糖压碎，大概熬 2 分钟","group":"开始制作"},{"text":"熬成糖色后，放入焯过水的猪蹄，继续小火，翻炒猪蹄，直至所有猪蹄两面微黄","group":"开始制作"},{"text":"加入香叶 2 片、桂皮 1 块、八角 4 个、生抽 20 ml、老抽 20 ml、料酒 10 ml、姜 3 片、盐 8 克，转中火、继续翻炒 1 分钟","group":"开始制作"},{"text":"加入开水或者冷水，水需要没过猪蹄，盖上锅盖，大火烧开，烧开之后关火","group":"开始制作"},{"text":"把锅内的食材全部倒入高压锅中，高压锅中需要 15 分钟（如果同学没有高压锅，可放在锅中大火转小火熬制即可）","group":"开始制作"},{"text":"15 分钟之后，把高压锅的食材倒入炒锅中，开大火收汁，此时可用筷子尝下味道、淡的话可以加 2~3g 盐","group":"开始制作"},{"text":"大火收汁时长根据锅中的水来算，一般 30 秒即可，多留点也无碍、红烧猪蹄汤也是很下饭的","group":"开始制作"}],"tips":[]},
{"id":"hunanjiachanghongshaorou","name":"湖南家常红烧肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/湖南家常红烧肉/湖南家常红烧肉.jpeg","hasImage":true,"difficulty":3,"difficultyText":"★★★","calories":"1348 大卡","time":"","servings":"1人份","description":"湖南家常红烧肉是一道湘味浓郁的家常菜，五花肉经慢炖后肥而不腻、入口软糯，咸香中带着微辣回甘。富含优质蛋白和脂肪，能为身体提供充足能量。制作需要一些耐心，对新手有一定挑战，但按步骤操作不难掌握，预计全程约 1 小时。","tags":[],"ingredients":[{"name":"五花肉：500g","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"食用油：10g","amount":"","optional":false,"amountValue":null,"amountUnit":""},{"name":"香叶","amount":"5 片","optional":false,"amountValue":5,"amountUnit":"片"},{"name":"姜","amount":"3 片","optional":false,"amountValue":3,"amountUnit":"片"},{"name":"桂皮","amount":"1 小块","optional":false,"amountValue":null,"amountUnit":""},{"name":"冰糖","amount":"6 颗","optional":false,"amountValue":6,"amountUnit":"颗"},{"name":"料酒","amount":"20 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"生抽","amount":"5 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"老抽","amount":"2 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐","amount":"2 克","optional":false,"amountValue":null,"amountUnit":""},{"name":"八角","amount":"3 颗","optional":false,"amountValue":3,"amountUnit":"颗"}],"steps":[{"text":"带皮五花肉洗净冷水下锅，加入姜片 2~3 片去腥味，煮到沸腾捞出冷水冲净白沫","group":""},{"text":"五花肉切块，尺寸 1.5cm*1.5cm 块状大小","group":""},{"text":"热锅加入油，加入冰糖小火搅拌至焦糖色即可，加入切好的五花肉，中火翻炒上色","group":""},{"text":"加入备好的姜片、八角、桂皮、生抽、老抽、料酒、干小米椒、盐，小火翻炒 1 分钟，加开水没过肉","group":""},{"text":"加盖中火煮沸，转小火慢顿 30 分钟，慢炖期间，间隔 10 分钟搅拌一次防止粘锅","group":""},{"text":"小火慢炖汤汁剩三分之一的时，调成中火收汁出锅。","group":""}],"tips":[]},
{"id":"hupizhouzi","name":"虎皮肘子","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":5,"difficultyText":"★★★★★","calories":"1018 大卡","time":"","servings":"1人份","description":"这道菜成品色泽红亮，肘皮呈现诱人的虎皮纹路，口感软烂入味，肥而不腻，瘦肉松软，属于传统中式宴客大菜。猪肘富含胶原蛋白和优质蛋白，经过长时间炖煮后更易吸收，对皮肤和关节有一定滋养效果。制作过程包含烧皮、油炸、炒糖色和高压炖煮等多个步骤，对新手来说挑战较大，建议有一定烹饪基础再尝试。从预处理到上桌，预计总耗时约 2.5 小时。","tags":["汤","进阶挑战"],"ingredients":[{"name":"1 汤匙","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"1 茶匙","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"猪肘解冻后水泡 1 小时去除血水。","group":"预处理"},{"text":"如有火焰喷枪，则使用火焰喷枪灼烧**猪肘皮**表面至**棕黑色**以去除猪毛，破坏汗腺。注意不要长时间炙烤同一个位置以避免烧焦，当猪肘皮几乎完全呈现棕黑色时则停止灼烧。","group":"预处理"},{"text":"如无火焰喷枪，将铁锅烧至 200 以上，将猪肘直接放入锅内，用锅铲或筷子使猪肘皮充分接触铁锅表面，当猪肘皮与铁锅接触位置呈现出棕色时，更换位置继续烫猪肘皮，直到整个猪肘被充分烫过。注意再次过程中注意铁锅温度，不要使铁锅红热。","group":"预处理"},{"text":"使用清洁球在水中刷洗猪肘，将其表面烧焦的部分去除。刷洗结束后，猪肘再次呈现出未被灼烧前的状态。","group":"预处理"},{"text":"将猪肘置于铁锅中，加尽量多的冷水，具体视铁锅深度与猪肘大小而定，在保证可以拿得动铁锅及其内容物的情况下，能浸没猪肘 3/4 以上为最佳。","group":"预处理"},{"text":"取 1 棵葱的葱白，分成 3 段，放入锅中。","group":"去腥"},{"text":"取 3 粒蒜，分别用刀身拍扁，放入锅中。","group":"去腥"},{"text":"取 3 克姜，放入锅中。","group":"去腥"},{"text":"将 2 汤匙料酒加入锅中。","group":"去腥"},{"text":"锅中水烧开后，等待五分钟，随后将猪肘取出，捡出锅中所有配料，更换容器保留所有肉汤备用。","group":"去腥"},{"text":"向锅中加入冷油，以之前水量为参考，能浸没猪肘 3/5 以上为佳，开中火加热。","group":"油炸"},{"text":"当[油温](tips/advanced/油温判断技巧.md)达到五成时，转为小火，放入猪肘油炸。","group":"油炸"},{"text":"在油炸过程中烹饪者应注意人身安全。","group":"油炸"},{"text":"在油炸过程中，使用锅铲或其他耐高温厨具将锅中的油均匀淋到猪肘未被浸没的部分，如果条件允许应以 3 分钟的间隔翻转猪肘，使其油炸均匀。","group":"油炸"},{"text":"油炸过程持续大约 20 分钟，当观察到猪肘皮已经全部呈现出浅棕色，而瘦肉部分已经微焦，则可捞出备用。","group":"油炸"},{"text":"炸制完后的油可用于制作其他油炸类食物，但注意不要使用太多次。","group":"油炸"},{"text":"[炒糖色](../../tips/advanced/糖色的炒制.md)200ml 备用。","group":"炒糖色"},{"text":"将猪肘加入高压锅内，加入所有肉汤、糖色、香叶、肉桂皮、豆蔻、花椒、大料、老抽、生抽、白醋。如果喜欢甜口，可以再额外加入 2-3 克冰糖。","group":"炖煮"},{"text":"取 1 棵葱的葱白，分成 3 段，放入锅中。","group":"炖煮"},{"text":"取 3 粒蒜，分别用刀身拍扁，放入锅中。","group":"炖煮"},{"text":"取 3 克姜，放入锅中。","group":"炖煮"},{"text":"盖上锅盖，加压炖煮 40 分钟。","group":"炖煮"},{"text":"在炖煮期间调制水淀粉。取碗 1 个，加入 1 汤匙淀粉，100ml 水，搅拌使其成为白色悬浊液","group":"收汁"},{"text":"炖煮时间结束后，打开高压锅锅盖，捡出锅中所有的配料，只保留猪肘。","group":"收汁"},{"text":"将高压锅中剩余的肉汤转移至铁锅内，猪肘转移至盘子或盆内","group":"收汁"},{"text":"将铁锅置于灶台上，开大火。在收汁过程中可以用筷子头蘸取锅内汤汁判断咸淡，并根据口味添加盐。注意，汤汁多的时候味道会比汤汁少的时候味道更淡，加入盐时需要考虑这一点。","group":"收汁"},{"text":"当肉汤沸腾时，注意观察剩余肉汤余量","group":"收汁"},{"text":"当剩余肉汤少于原肉汤体积的 1/2 时，再次搅拌之前调制好的水淀粉，并加入一半","group":"收汁"},{"text":"等待肉汤沸腾，加入剩下的一半","group":"收汁"},{"text":"等待肉汤沸腾，沸腾后等待 1-2 分钟关火，此时锅内的肉汤呈红棕色粘稠状","group":"收汁"},{"text":"用汤匙舀起肉汤均匀地淋在猪肘上，尽量使猪肘的每一处都淋到汤汁。如果在猪肘被完全淋到前汤汁已经用完则可直接上桌，否则剩余汤汁不需要再淋，可直接上桌。","group":"收汁"}],"tips":["参考资料：Bilibili老饭骨的视频教程"]},
{"id":"huangguachaorou","name":"黄瓜炒肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"550 大卡","time":"","servings":"1人份","description":"这是一道清爽脆嫩的家常快手菜，咸鲜适口，带有蒜香与微辣。富含蛋白质和多种维生素，有助于清热补水。对新手比较友好，只要注意火候就能成功，预计制作时长约 25 分钟。","tags":["辣"],"ingredients":[{"name":"黄瓜","amount":"100 克  * 份数","optional":false,"amountValue":null,"amountUnit":""},{"name":"猪肉","amount":"50 克  * 份数","optional":false,"amountValue":null,"amountUnit":""},{"name":"油量","amount":"50 克 * 份数","optional":false,"amountValue":null,"amountUnit":""},{"name":"盐量","amount":"10  克  * 份数","optional":false,"amountValue":null,"amountUnit":""},{"name":"酱油","amount":"5  克  * 份数","optional":false,"amountValue":null,"amountUnit":""},{"name":"蒜瓣","amount":"2  瓣  * 份数","optional":false,"amountValue":2,"amountUnit":"瓣"},{"name":"小米辣","amount":"1  根  * 份数","optional":false,"amountValue":1,"amountUnit":"根"}],"steps":[{"text":"将猪瘦肉切片，放入碗中，倒入食用油 10 克，生抽，搅拌均匀，腌制 10 分钟","group":""},{"text":"将黄瓜切去 5 厘米的头尾，剩余部分斜着切成 0.5 厘米的薄片","group":""},{"text":"将黄瓜倒入碗中，撒上盐 8 克，搅拌均匀，腌制 5 分钟","group":""},{"text":"将蒜瓣去皮，压扁，切成蒜末备用","group":""},{"text":"将小米辣去丁切分成均匀 0.5 厘米的段状","group":""},{"text":"热锅，倒油 40 克，等油温到冒烟，放入蒜蓉小米辣翻炒 5 次","group":""},{"text":"放入腌制好的猪瘦肉，翻炒至肉熟变色","group":""},{"text":"放入黄瓜，加入盐 2 克，大火翻炒均匀半分钟，出锅","group":""},{"text":"如果无法保证大火，可能会有点生。可以考虑增加到 50 秒。","group":""}],"tips":[]},
{"id":"huangmenji","name":"黄焖鸡","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":3,"difficultyText":"★★★","calories":"766 大卡","time":"40分钟","servings":"1人份","description":"黄焖鸡是一道以鸡腿、香菇、青椒为主料的家常菜，汤汁浓郁，鸡肉滑嫩，咸鲜微甜，十分下饭。富含优质蛋白质和菌菇多糖等营养。炒糖色环节稍有挑战，但可用老抽替代，整体难度不高，新手也能顺利掌握。从备菜到出锅，大约需要 40 分钟。","tags":["辣"],"ingredients":[{"name":"鸡腿","amount":"两只","optional":false,"amountValue":null,"amountUnit":""},{"name":"香菇（干香菇最佳）","amount":"5 朵","optional":false,"amountValue":5,"amountUnit":"朵"},{"name":"青椒","amount":"两个","optional":false,"amountValue":null,"amountUnit":""},{"name":"生姜片","amount":"两片","optional":false,"amountValue":null,"amountUnit":""},{"name":"干辣椒","amount":"5，6 个","optional":false,"amountValue":6,"amountUnit":"个"},{"name":"盐","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"料酒","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"白胡椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"白糖","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"酱油","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"土豆","amount":"一个（可选，可使汤汁更粘稠）","optional":true,"amountValue":null,"amountUnit":""}],"steps":[{"text":"鸡腿洗净，剁成**4cm**大小的块","group":"备菜阶段"},{"text":"生姜切片、干辣椒切成**小圈**","group":"备菜阶段"},{"text":"香菇切片，青椒切成细长的**马蹄状**，若为干香菇，洗净灰尘后泡一晚上并留香菇水备用","group":"备菜阶段"},{"text":"若有土豆，切为与鸡肉大小类似的**滚刀块**","group":"备菜阶段"},{"text":"炒糖色：锅里倒入底油，冷油时放入白糖（**有一定难度，新手可跳至鸡肉炒制并使用老抽替代**）","group":"炒制阶段"},{"text":"小火慢慢加热，待油温逐渐升高，白糖开始融化并变成较深的棕色（期间要不断搅拌，防止糊锅）","group":"炒制阶段"},{"text":"迅速倒入鸡块，转大火，快速翻炒！烹入料酒，继续翻炒片刻","group":"炒制阶段"},{"text":"将生姜片和干辣椒倒入","group":"炒制阶段"},{"text":"放入酱油，炒匀","group":"炒制阶段"},{"text":"倒入香菇水或清水，以能淹住鸡肉为准","group":"炒制阶段"},{"text":"倒入香菇片，白胡椒粉，盐，土豆","group":"炒制阶段"},{"text":"翻炒均匀后，盖上锅盖焖煮，转中小火**15——20分钟**，有条件可以转至砂锅","group":"炒制阶段"},{"text":"待鸡肉软烂，汤汁浓稠后（汤汁不要收的太干），最后放入青椒","group":"炒制阶段"},{"text":"放入味精，兜炒均匀后，关火！青椒基本断生即可，不要炒时间久了","group":"炒制阶段"}],"tips":[]},
{"id":"huangyouji","name":"黄油鸡","category":"荤菜","categoryKey":"meat_dish","emoji":"🍗","color":"#FFB3A7","light":"#FFF0ED","image":null,"hasImage":false,"difficulty":4,"difficultyText":"★★★★","calories":"641 大卡","time":"","servings":"1-2人份","description":"这是一道源自印度的经典咖喱菜肴，以烤制后再炖煮的鸡腿肉搭配番茄、黄油和奶油制成的酱汁，口感醇厚丝滑，酸甜微辣，带有独特的香料复合香气。鸡肉、酸奶和腰果提供了丰富的蛋白质与健康脂肪，番茄和香料也带来一定的维生素与抗氧化物。制作有一定挑战，需要掌握火候和香料的平衡，加上腌制时间共约 1 小时 45 分钟方可完成。","tags":["辣","进阶挑战"],"ingredients":[{"name":"鸡腿肉","amount":"500g（去骨，切大块）","optional":false,"amountValue":500,"amountUnit":"g"},{"name":"酸奶","amount":"80ml","optional":false,"amountValue":80,"amountUnit":"ml"},{"name":"生姜","amount":"10g，磨碎","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"大蒜","amount":"4 瓣（约 12g），磨碎","optional":false,"amountValue":4,"amountUnit":"瓣"},{"name":"红辣椒粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"姜黄粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"盐","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"柠檬汁","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"食用油","amount":"15ml","optional":false,"amountValue":15,"amountUnit":"ml"},{"name":"番茄","amount":"5 个（约 500g），切块","optional":false,"amountValue":5,"amountUnit":"个"},{"name":"洋葱","amount":"1 个（约 100g），切块","optional":false,"amountValue":1,"amountUnit":"个"},{"name":"腰果","amount":"30g","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"生姜","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"大蒜","amount":"4 瓣","optional":false,"amountValue":4,"amountUnit":"瓣"},{"name":"黄油","amount":"50g","optional":false,"amountValue":50,"amountUnit":"g"},{"name":"淡奶油","amount":"100ml","optional":false,"amountValue":100,"amountUnit":"ml"},{"name":"红辣椒粉","amount":"5g（Kashmiri 红辣椒粉最佳）","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"香菜粉","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"孜然粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"印度综合香料粉","amount":"3g","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"小豆蔻粉","amount":"2g","optional":false,"amountValue":2,"amountUnit":"g"},{"name":"干葫芦巴叶","amount":"3g（用手搓碎）","optional":false,"amountValue":3,"amountUnit":"g"},{"name":"糖","amount":"10g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"盐","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"水","amount":"100ml","optional":false,"amountValue":100,"amountUnit":"ml"}],"steps":[{"text":"在大碗中混合酸奶、生姜泥、大蒜泥、红辣椒粉、姜黄粉、盐、柠檬汁","group":"腌制鸡肉（提前 1 小时）"},{"text":"放入鸡肉块，充分裹上腌料","group":"腌制鸡肉（提前 1 小时）"},{"text":"盖保鲜膜，冷藏腌制**至少 1 小时**","group":"腌制鸡肉（提前 1 小时）"},{"text":"在平底锅中倒入 15ml 食用油，大火加热","group":"烤制鸡肉"},{"text":"将腌好的鸡肉块放入锅中（不要倒入腌料汁）","group":"烤制鸡肉"},{"text":"大火煎至*两面焦黄*（每面约 3 分钟），鸡肉不需要完全煮熟","group":"烤制鸡肉"},{"text":"盛出备用","group":"烤制鸡肉"},{"text":"在锅中放入番茄块、洋葱块、腰果、生姜、大蒜和水 100ml","group":"制作酱汁底料"},{"text":"大火煮沸后转中火，**煮 15 分钟**，直至*所有材料完全软烂*","group":"制作酱汁底料"},{"text":"稍微冷却后，倒入搅拌机中打成*细腻顺滑的泥状*","group":"制作酱汁底料"},{"text":"用滤网过滤一遍，去除渣滓，得到顺滑的酱汁，备用","group":"制作酱汁底料"},{"text":"在炒锅中放入黄油 50g，中火加热融化","group":"炖煮"},{"text":"倒入过滤好的番茄酱汁","group":"炖煮"},{"text":"加入红辣椒粉 5g、香菜粉 5g、孜然粉 3g、盐 5g","group":"炖煮"},{"text":"翻炒 **3-5 分钟**，直至*酱汁颜色变深且油花浮出*","group":"炖煮"},{"text":"放入烤好的鸡肉块，翻拌均匀","group":"炖煮"},{"text":"加入糖 10g（平衡番茄的酸味），搅拌","group":"炖煮"},{"text":"倒入淡奶油 100ml，搅拌均匀","group":"炖煮"},{"text":"小火**炖 10-12 分钟**，使鸡肉完全熟透且吸收酱汁","group":"炖煮"},{"text":"加入印度综合香料粉 3g、小豆蔻粉 2g","group":"炖煮"},{"text":"撒入干葫芦巴叶 3g（用手搓碎后撒入）","group":"炖煮"},{"text":"搅拌均匀，关火","group":"炖煮"},{"text":"盛盘，可额外淋上少量淡奶油作为装饰","group":"炖煮"}],"tips":["干葫芦巴叶(Kasuri Methi)是这道菜独特风味的关键配料，能赋予一种特殊的草本香气。在印度食品店或电商平台可以购买到。","使用 Kashmiri 红辣椒粉可以使颜色更鲜红但辣度较低。如果买不到，可以用普通红辣椒粉减半并加入 3g 红甜椒粉。","腰果的作用是使酱汁更加浓稠丝滑。如果对坚果过敏，可以用等量的淡奶油替代。","此菜通常搭配印度烤饼(Naan)或巴斯马蒂米饭食用。","黄油鸡被认为是印度对世界美食最大的贡献之一，在全球各地的印度餐厅菜单上几乎都名列前茅。"]},
{"id":"huipaihongshaorou","name":"徽派红烧肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/徽派红烧肉/1.jpeg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"3847 大卡","time":"","servings":"1-2人份","description":"徽派红烧肉是一道色泽红亮、肥而不腻的经典徽式家常菜，口感软糯 Q 弹，咸甜交融。以五花肉为主料，富含优质蛋白质和脂肪，能提供充沛能量。烹制需掌握炒糖色与火候，稍有挑战，预估制作时长约 45 分钟。","tags":["进阶挑战"],"ingredients":[{"name":"五花肉","amount":"300 g","optional":false,"amountValue":300,"amountUnit":"g"},{"name":"白砂糖","amount":"100 g","optional":false,"amountValue":100,"amountUnit":"g"},{"name":"食用油","amount":"200 g","optional":false,"amountValue":200,"amountUnit":"g"},{"name":"生抽","amount":"10 ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"蚝油","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"老抽","amount":"5 ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"姜片","amount":"2 片","optional":false,"amountValue":2,"amountUnit":"片"},{"name":"蒜头","amount":"3 颗","optional":false,"amountValue":3,"amountUnit":"颗"},{"name":"料酒","amount":"100 ml","optional":false,"amountValue":100,"amountUnit":"ml"},{"name":"葱","amount":"1 根","optional":false,"amountValue":1,"amountUnit":"根"},{"name":"五香粉","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"},{"name":"盐","amount":"10 g","optional":false,"amountValue":10,"amountUnit":"g"}],"steps":[{"text":"五花肉切块，每块 2-3 cm 大小","group":""},{"text":"锅中加入 150 ml 食用油，倒入五花肉，煎炸 2 分钟 后，加入盐，翻炒五花肉，2 分钟 后出锅","group":""},{"text":"锅中加入 50 ml 食用油，倒入白砂糖，翻炒到咖啡色","group":""},{"text":"倒入五花肉，翻炒 30 S ，加入姜片、蒜头后翻炒 30 S","group":""},{"text":"加入料酒，五香粉、葱，加入水没过五花肉，盖上锅盖煮 10 分钟","group":""},{"text":"加入生抽、老抽、蚝油，中火煮 20 分钟","group":""},{"text":"开锅，大火烧汁，端盘","group":""}],"tips":["葱是整根，不需要切碎","步骤二加盐的目的是锁住五花肉的油脂","制作过程，用部分五花肉做了水煮处理，跟未处理的一起做后续制作，发现未水煮的肉质更 Q 弹"]},
{"id":"huiguorou","name":"回锅肉","category":"荤菜","categoryKey":"meat_dish","emoji":"🍖","color":"#FFB3A7","light":"#FFF0ED","image":"dishes/meat_dish/回锅肉/1.jpeg","hasImage":true,"difficulty":4,"difficultyText":"★★★★","calories":"997 大卡","time":"","servings":"1人份","description":"回锅肉是四川传统名菜，以二刀肉或五花肉为主料，成菜色泽红亮，肥肉透明微卷、瘦肉干香不柴，口感肥而不腻，咸鲜微辣，带有蒜苗与豆瓣酱的复合香气。猪肉富含优质蛋白和必需脂肪酸，搭配青红椒、蒜苗可补充维生素。这道菜步骤稍多，包含煮、切、煸炒，对火候和刀工有一定要求，但按流程操作新手也能成功，预计全程耗时约 40 分钟。","tags":["辣","进阶挑战"],"ingredients":[{"name":"五花肉的用量为","amount":"0.5 斤/男人 0.3 斤/女人 （正宗回锅肉使用二刀肉[俗称：臀尖]制作，肉质坚实，肥瘦合适）","optional":false,"amountValue":0.5,"amountUnit":"斤"},{"name":"小葱","amount":"2 棵","optional":false,"amountValue":null,"amountUnit":""},{"name":"生姜","amount":"10-40g","optional":false,"amountValue":40,"amountUnit":"g"},{"name":"青红椒（根据受辣程度选择,","amount":"0-30g）*注：不建议使用肉厚的菜椒","optional":false,"amountValue":30,"amountUnit":"g"},{"name":"蒜苗","amount":"1 把","optional":false,"amountValue":null,"amountUnit":""},{"name":"料酒","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"},{"name":"豆瓣酱","amount":"10ml","optional":false,"amountValue":10,"amountUnit":"ml"},{"name":"味精","amount":"5g","optional":false,"amountValue":5,"amountUnit":"g"},{"name":"生抽","amount":"5ml","optional":false,"amountValue":5,"amountUnit":"ml"}],"steps":[{"text":"锅烧热，用手将五花肉紧紧压在锅上炙皮","group":"五花肉一段处理"},{"text":"这一步是为了处理猪皮上的汗腺（或者买肉的时候让师傅烧一下皮，喜欢汗腺的可以无视）","group":"五花肉一段处理"},{"text":"用钢丝球把皮刷干净，至黑色部分碳化部分被完全去除，不刷干净会有苦味","group":"五花肉一段处理"},{"text":"将五花肉放入锅中，放入能淹没五花肉的冷水，放入生姜片、料酒和小葱（取 2 棵小葱打结）","group":"五花肉一段处理"},{"text":"开大火煮，水开后撇去浮沫，继续煮 15 分钟，煮至瘦肉部分可以用筷子轻松刺穿","group":"五花肉一段处理"},{"text":"青红椒切圈","group":"配菜处理"},{"text":"蒜苗切段","group":"配菜处理"},{"text":"生姜切小薄片","group":"配菜处理"},{"text":"将 5ml 豆瓣酱和 5ml 生抽提前混合","group":"配菜处理"},{"text":"将煮熟的五花肉捞出放入冷水晾凉","group":"五花肉二段处理"},{"text":"擦干五花肉的水，切成上肥下瘦的 2mm 的薄片（切厚了口感不好，而且很油）","group":"五花肉二段处理"},{"text":"锅烧热，放入一层底油滑锅","group":"开始炒肉"},{"text":"放入五花肉煸炒至肥肉透明，肉片微卷（欲称起灯盏窝），二刀肉效果最佳。","group":"开始炒肉"},{"text":"倒入豆瓣生抽混合物，5g 味精翻炒 15 秒","group":"开始炒肉"},{"text":"放入青红椒圈和小姜片，放入另 5ml 豆瓣酱翻炒 30 秒","group":"开始炒肉"},{"text":"放入蒜苗翻炒 60 秒","group":"开始炒肉"},{"text":"出锅","group":"开始炒肉"},{"text":"选用冰冻五花肉常量放置 0.5 小时 或者鲜五花肉放冰箱冷藏 1 个小时，切成 2-5 mm 薄片","group":"简易版本"},{"text":"开中火，辣椒放过锅中干煸 30-45 秒后取出","group":"简易版本"},{"text":"锅烧热，放入一层底油滑锅，放入姜片煸炒 15 秒","group":"简易版本"},{"text":"倒入五花肉，间隔 10 S 翻炒一次，待五花肉出现焦黄色（翻炒时间越久五花肉口感越硬）","group":"简易版本"},{"text":"倒入之前干煸过的辣椒、10ml 豆瓣酱，生抽调味，继续翻炒 60 秒","group":"简易版本"},{"text":"倒入切成段的蒜苗翻炒 10 秒","group":"简易版本"},{"text":"出锅","group":"简易版本"}],"tips":["不喜欢蒜苗可以换成洋葱或者其他蔬菜，但是要注意蔬菜的易熟程度将蔬菜提前炒至，不然会出现蔬菜半生不熟的情况","如果回锅肉比较大块可以切成 5 厘米见方的块，五花肉煮至筷子稍微用力即可插入猪皮即可","回锅肉过冷水晾凉后肉质会更紧致","回锅肉擦干水是为了避免炒至的时候爆油溅伤","回锅肉切记不要切厚了，不然很腻"]}
];
